  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'issued',
    number: 'INV-2026-0001',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 5,
        unitPrice: 9500,
        vatRate: 21,
      },
    ],
  };

  const result = issueInvoice(invoice, []);
  assert.equal(result.ok, false);
  assert.equal(result.error, 'NOT_DRAFT');
});

test('issueInvoice: does not mutate original invoice', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result1.ok, true);

  const original = JSON.parse(JSON.stringify(result1.value));
  issueInvoice(result1.value, []);

  assert.deepEqual(result1.value, original);
});

test('issueInvoice: preserves all line data', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.equal(result1.ok, true);

  const result2 = issueInvoice(result1.value, []);

  assert.equal(result2.ok, true);
  assert.equal(result2.value.lines.length, 2);
  assert.deepEqual(result2.value.lines[0], {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
    discountPercent: 5,
  });
  assert.deepEqual(result2.value.lines[1], {
    sku: 'DES-HOUR',
    name: 'Design work (hour)',
    qty: 5,
    unitPrice: 8500,
    vatRate: 21,
    discountPercent: 5,
  });
});

test('issueInvoice: different years get different counters', () => {
  const result1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-31',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result1.ok, true);

  const result2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-01-01',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });

  assert.equal(result2.ok, true);

  const existing2025 = ['INV-2025-0001', 'INV-2025-0002'];
  const result3 = issueInvoice(result1.value, existing2025);
  assert.equal(result3.value.number, 'INV-2025-0003');

  const existing2026 = [];
  const result4 = issueInvoice(result2.value, existing2026);
  assert.equal(result4.value.number, 'INV-2026-0001');
});
